Here is the complete Java implementation for the Asia Pacific Airport simulation (`AirportSim.java`), along with the sample output and presentation script.

```java
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.concurrent.locks.*;

public class AirportSim {
    static final Semaphore groundCap = new Semaphore(3, true);
    static final ReentrantLock runway = new ReentrantLock(true);
    static final ReentrantLock fuelTruck = new ReentrantLock(true);
    static final BlockingQueue<Integer> gates = new ArrayBlockingQueue<>(3);
    static final PriorityBlockingQueue<Plane> queue = new PriorityBlockingQueue<>();
    static final AtomicInteger totalPax = new AtomicInteger(0), planesServed = new AtomicInteger(0);
    static final List<Long> waits = Collections.synchronizedList(new ArrayList<>());

    static void log(String msg) { System.out.println(Thread.currentThread().getName() + " : " + msg); }

    static class Plane extends Thread implements Comparable<Plane> {
        int id; boolean emerg; long arrTime;
        Plane(int id, boolean emerg) {
            super("Thread-Plane-" + id); this.id = id; this.emerg = emerg;
        }
        public int compareTo(Plane o) {
            return this.emerg != o.emerg ? (this.emerg ? -1 : 1) : Long.compare(this.arrTime, o.arrTime);
        }
        public void run() {
            try {
                arrTime = System.currentTimeMillis();
                log("Requesting permission to land!" + (emerg ? " [EMERGENCY]" : ""));
                queue.put(this);
                int gate = -1;
                synchronized (queue) {
                    while (queue.peek() != this || !groundCap.tryAcquire()) queue.wait(100);
                    queue.poll();
                    gate = gates.take();
                    System.out.println("Thread-ATC : Granted landing for Plane " + id + " at Gate " + gate);
                }
                waits.add(System.currentTimeMillis() - arrTime);
                runway.lock(); log("Landing on runway..."); Thread.sleep(500);
                log("Coasting to Gate " + gate); runway.unlock();
                log("Docked at Gate " + gate);

                Thread paxT = new Thread(() -> {
                    int p = new Random().nextInt(21) + 30;
                    log("Disembarking and embarking " + p + " passengers for Plane " + id);
                    try { Thread.sleep(600); } catch (Exception e) {}
                    totalPax.addAndGet(p);
                }, "Thread-Pax-Plane-" + id);
                Thread cleanT = new Thread(() -> {
                    log("Cleaning and refilling supplies for Plane " + id);
                    try { Thread.sleep(600); } catch (Exception e) {}
                }, "Thread-Crew-Plane-" + id);
                paxT.start(); cleanT.start();

                fuelTruck.lock(); log("Refuelling with exclusive truck..."); Thread.sleep(500); fuelTruck.unlock();
                paxT.join(); cleanT.join();

                log("Undocking from Gate " + gate);
                runway.lock(); log("Coasting to runway and taking off..."); Thread.sleep(500); runway.unlock();
                gates.put(gate); groundCap.release(); planesServed.incrementAndGet();
                synchronized (queue) { queue.notifyAll(); }
            } catch (Exception e) { e.printStackTrace(); }
        }
    }

    public static void main(String[] args) throws Exception {
        gates.addAll(Arrays.asList(1, 2, 3));
        Random rand = new Random();
        Plane[] planes = new Plane[6];
        for (int i = 0; i < 6; i++) {
            planes[i] = new Plane(i + 1, i == 4);
            planes[i].start();
            Thread.sleep(rand.nextInt(2000));
        }
        for (Plane p : planes) p.join();
        System.out.println("\n--- Thread-ATC : SANITY CHECK & STATISTICS ---");
        System.out.println("All Gates Empty: " + (gates.size() == 3));
        System.out.println("Planes Served: " + planesServed.get() + " | Total Passengers: " + totalPax.get());
        System.out.println("Wait Time (ms) - Max: " + Collections.max(waits) + ", Min: " + Collections.min(waits) + 
                           ", Avg: " + waits.stream().mapToLong(v->v).average().orElse(0));
    }
}
```

